body {
  background: transparent !important;
}

.chat-me-id,
.chat-me-sheet {
  background: rgba(200, 200, 200, 0.25) !important; 
  backdrop-filter: blur(20px) saturate(120%) !important;
  -webkit-backdrop-filter: blur(20px) saturate(120%) !important;
  border: 1px solid rgba(255, 255, 255, 0.4) !important; 
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.05) !important; 
  border-radius: 16px !important; 
  overflow: hidden !important; 
  transition: all 0.3s ease !important;
}

html[data-theme="dark"] .chat-me-id,
html[data-theme="dark"] .chat-me-sheet,
body.dark-mode .chat-me-id,
body.dark-mode .chat-me-sheet {
  background: rgba(30, 30, 30, 0.4) !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important; 
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2) !important; 
}

.chat-me-id > button,
.chat-me-sheet > div,
.chat-me-sheet > a,
.chat-me-sheet > button {
  background-color: transparent !important;
  border: none !important;
}

.chat-me-id > button:hover,
.chat-me-sheet > a:hover,
.chat-me-sheet > button:hover {
  background: rgba(255, 255, 255, 0.1) !important;
}
html[data-theme="dark"] .chat-me-id > button:hover,
html[data-theme="dark"] .chat-me-sheet > a:hover,
html[data-theme="dark"] .chat-me-sheet > button:hover {
  background: rgba(255, 255, 255, 0.05) !important;
}

.app-screen.chat-app,
.chat-main,
.chat-scroll.chat-scroll-me,
.chat-me-edit.persona-app {
    background: transparent !important;
    background-color: transparent !important;
}


.persona-editor-head,
.persona-sheet {

    background: rgba(30, 30, 30, 0.45) !important;
    backdrop-filter: blur(25px) saturate(150%) !important;
    -webkit-backdrop-filter: blur(25px) saturate(150%) !important;
    border: 1px solid rgba(255, 255, 255, 0.12) !important;
    border-radius: 16px !important;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3) !important;
    overflow: hidden !important;
    margin-bottom: 16px !important; 
}

html[data-theme="light"] .persona-editor-head,
html[data-theme="light"] .persona-sheet {
    background: rgba(255, 255, 255, 0.3) !important;
    border: 1px solid rgba(255, 255, 255, 0.6) !important;
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.05) !important;
}

.persona-editor-head *,
.persona-sheet > div,
.persona-sheet .persona-section-row, 
.persona-sheet input,
.persona-sheet textarea,
.persona-sheet select,
.persona-sheet button {
    background: transparent !important;
    background-color: transparent !important;
    box-shadow: none !important; 
}

.persona-sheet input,
.persona-sheet textarea {
    border: none !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.2) !important;
    border-radius: 0 !important;
}
html[data-theme="light"] .persona-sheet input,
html[data-theme="light"] .persona-sheet textarea {
    border-bottom: 1px solid rgba(0, 0, 0, 0.1) !important;
}
